mapper.select:
select DATE_FORMAT(stat_date,#{param.groupFormat}) as time,sum(d_value) as value from energy_daily_usage_project
where deleted = 0 and project_category = #{param.projectCategory}

    and instrument_type = #{param.instrumentType}


    and project_id in

        #{projectId}



    and stat_date >= #{param.period.begin}


    and stat_date <= #{param.period.end}

group by time

select DATE_FORMAT(stat_date,#{param.groupFormat}) as time,project_name as name,sum(d_value) as value from
energy_daily_usage_project
where deleted = 0 and project_category = #{param.projectCategory}

    and instrument_type = #{param.instrumentType}


    and project_id in

        #{projectId}



    and stat_date >= #{param.period.begin}


    and stat_date <= #{param.period.end}

group by time,project_name

select project_name as name,sum(d_value) as value,sum(dc_value) as dcValue,sum(zh_value) as zhValue from energy_daily_usage_project
where deleted = 0 and project_category = #{param.projectCategory}

    and instrument_type = #{param.instrumentType}


    and project_id in

        #{projectId}



    and stat_date >= #{param.period.begin}


    and stat_date <= #{param.period.end}

group by project_name order by `value` desc

select p.project_category,p.instrument_type,p.project_id,p.project_name,ep.parent_id,ep.sequence,sum(p.d_value) as value
from energy_daily_usage_project p
left join area_project ep on ep.id = p.project_id
where p.deleted = 0 and p.project_category = #{param.projectCategory}

    and instrument_type = #{param.instrumentType}


    and stat_date >= #{param.period.begin}


    and stat_date <= #{param.period.end}

group by p.project_category,p.instrument_type,p.project_id

select edup.project_id as project_id ,edup.instrument_type_name, ap.area_name as name,sum(d_value) as value,sum(dc_value) as
dcValue,sum(zh_value) as zhValue
from energy_daily_usage_project edup
left join area_project ap on (ap.id = edup.project_id)
where project_category = #{param.projectCategory}

    and edup.instrument_type = #{param.instrumentType}


    and edup.project_id in

        #{projectId}



    and edup.stat_date >= #{param.period.begin}


    and edup.stat_date <= #{param.period.end}

group by edup.project_id order by `value` desc

select edup.project_id as project_id ,edup.instrument_type_name, ep.project_name as name,sum(d_value) as value,sum(dc_value) as
dcValue,sum(zh_value) as zhValue
from energy_daily_usage_project edup
left join energy_project ep on (ep.id = edup.project_id)
where project_category = #{param.projectCategory}

    and edup.instrument_type = #{param.instrumentType}


    and edup.project_id in

        #{projectId}



    and edup.stat_date >= #{param.period.begin}


    and edup.stat_date <= #{param.period.end}

group by edup.project_id order by `value` desc
